#include <iostream>
#define str(s) # s  // Stringifies the argument s into a string literal
#define xstr(s) str(s)  // Indirect macro to allow further expansion before stringification
int main() {
    const char* strExample = xstr(Hello World);  // Expands to str(Hello World), which becomes "Hello World"
    std::cout << strExample << std::endl;  // Outputs: Hello World
    return 0;
}
